import { defineConfig } from "vite";
import solid from "vite-plugin-solid";
import { fileURLToPath } from "node:url";
import { readFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { rupokPwa } from "./pwa/plugin";

// Static marketing pages (/open/, /compare/…, /bn/…) generated by
// `node site/build.mjs`, which lists them in site/inputs.json.
const sitePages: string[] = JSON.parse(readFileSync(new URL("./site/inputs.json", import.meta.url), "utf8"));

// Which build this is, for Settings → About: the commit, and the branch when
// it is not main ("fix/smooth-curves@1a2b3c4"). RUPOK_BUILD overrides it;
// empty outside a git checkout (a source tarball).
function buildId(): string {
  if (process.env.RUPOK_BUILD !== undefined) return process.env.RUPOK_BUILD;
  const git = (...args: string[]) => {
    try {
      return execFileSync("git", args, { cwd: fileURLToPath(new URL(".", import.meta.url)), stdio: ["ignore", "pipe", "ignore"] }).toString().trim();
    } catch {
      return "";
    }
  };
  const commit = git("rev-parse", "--short", "HEAD");
  if (!commit) return "";
  // CI checks out a detached HEAD: take the branch from its environment.
  const branch = process.env.GITHUB_HEAD_REF || process.env.GITHUB_REF_NAME || git("rev-parse", "--abbrev-ref", "HEAD");
  return branch && branch !== "main" && branch !== "HEAD" ? `${branch}@${commit}` : commit;
}

export default defineConfig({
  // Served from the domain root: "/" is the website, "/board/" is the app.
  base: "/",
  define: { __RUPOK_BUILD__: JSON.stringify(buildId()) },
  plugins: [solid(), rupokPwa()], // rupokPwa: sw.js + version.json (pwa/plugin.ts)
  server: {
    port: 3737,
    host: "127.0.0.1",
    fs: { allow: ["../.."] },
    // Smart Objects run in opaque-origin frames (Origin: null); they load
    // /rupoklib/ modules and fonts, which need CORS.
    cors: { origin: "*" },
    // Dev only: Rupok Cloud (private repo, `npm run dev` on :8787) behind the
    // same origin, as in production (rupok.app/api, rupok.app/s). Override
    // with RUPOK_CLOUD_DEV=http://host:port.
    proxy: Object.fromEntries(
      ["/api/", "/s/"].map((p) => [p, { target: process.env.RUPOK_CLOUD_DEV ?? "http://127.0.0.1:8787", changeOrigin: true }]),
    ),
  },
  preview: { cors: { origin: "*" } },
  build: {
    target: "es2022",
    chunkSizeWarningLimit: 4096,
    rollupOptions: {
      input: {
        site: fileURLToPath(new URL("./index.html", import.meta.url)),
        board: fileURLToPath(new URL("./board/index.html", import.meta.url)),
        ...Object.fromEntries(
          sitePages.map((p) => [p.replace(/\/?index\.html$/, "").replaceAll("/", "-"), fileURLToPath(new URL(`./${p}`, import.meta.url))]),
        ),
      },
    },
  },
  optimizeDeps: { exclude: ["./src/wasm/rupok.js"] },
});
